public class ThreadLocalLeakExample {
    private static final ThreadLocal<byte[]> contextHolder = new ThreadLocal<>();

    public void processRequest(byte[] largePayload) {
        // Placing data into ThreadLocal
        contextHolder.set(largePayload);

        try {
            // Business logic execution
        } finally {
            // CRITICAL: Prevent memory leak in thread pools by clearing ThreadLocal
            contextHolder.remove();
        }
    }
}
